begin;
select plan(55);
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('58000000-0000-0000-0000-000000000001','authenticated','authenticated','phase8-a@example.test','',now(),'{}','{"name":"Phase8 A","company_name":"Phase8 A"}',now(),now()),
('58000000-0000-0000-0000-000000000002','authenticated','authenticated','phase8-b@example.test','',now(),'{}','{"name":"Phase8 B","company_name":"Phase8 B"}',now(),now());
select set_config('request.jwt.claims','{"sub":"58000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select set_config('phase8.a',public.finance_command('58000000-0000-0000-0000-000000000010','account_create','{"name":"Bank A","kind":"bank","amount":1000}')#>>'{account,id}',true);
select set_config('phase8.b',public.finance_command('58000000-0000-0000-0000-000000000011','account_create','{"name":"Bank B","kind":"bank","amount":0}')#>>'{account,id}',true);
select is((select count(*)::integer from public.financial_accounts),2,'creates accounts');
select is((public.finance_command('58000000-0000-0000-0000-000000000010','account_create','{"name":"Bank A","kind":"bank","amount":1000}')#>>'{account,id}'),current_setting('phase8.a'),'replay returns same result');
select is((select count(*)::integer from public.financial_accounts),2,'replay creates nothing');
select throws_ok($$select public.finance_command('58000000-0000-0000-0000-000000000010','account_create','{"name":"Changed","kind":"bank","amount":1000}')$$,'22023','Operation key reused','idempotency key cannot change payload');
select public.finance_command(gen_random_uuid(),'transfer',jsonb_build_object('account_id',current_setting('phase8.a'),'destination_id',current_setting('phase8.b'),'amount',100,'description','Transfer test'));
select is((select sum(case type when 'receita' then amount else -amount end) from public.financial_transactions where account_id=current_setting('phase8.a')::uuid),900::numeric,'A minus 100');
select is((select sum(case type when 'receita' then amount else -amount end) from public.financial_transactions where account_id=current_setting('phase8.b')::uuid),100::numeric,'B plus 100');
select is((select sum(case type when 'receita' then amount else -amount end) from public.financial_transactions where economic_kind='transfer'),0::numeric,'transfer consolidated neutral');
select is((select count(*)::integer from public.financial_transactions where economic_kind='transfer' and source='transfer'),2,'two classified transfer legs');
select lives_ok($$select public.finance_command(gen_random_uuid(),'account_update',(select to_jsonb(a)||'{"notes":"Edited locally"}'::jsonb from public.financial_accounts a where id=current_setting('phase8.b')::uuid))$$,'account metadata can be edited');
select lives_ok($$select public.finance_command(gen_random_uuid(),'adjust',jsonb_build_object('account_id',current_setting('phase8.b'),'type','receita','amount',20,'description','Audited correction'))$$,'account adjustment appends a movement');
select is((select sum(case type when 'receita' then amount else -amount end) from public.financial_transactions where account_id=current_setting('phase8.b')::uuid),120::numeric,'adjustment changes derived balance');
select lives_ok($$select public.finance_command(gen_random_uuid(),'account_update',(select to_jsonb(a)||'{"active":false}'::jsonb from public.financial_accounts a where id=current_setting('phase8.b')::uuid))$$,'account can be blocked');
select throws_ok($$select public.finance_command(gen_random_uuid(),'transfer',jsonb_build_object('account_id',current_setting('phase8.a'),'destination_id',current_setting('phase8.b'),'amount',10,'description','Blocked destination'))$$,'22023','Different active destination required','blocked destination rejects transfers');
select lives_ok($$select public.finance_command(gen_random_uuid(),'account_update',(select to_jsonb(a)||'{"active":true}'::jsonb from public.financial_accounts a where id=current_setting('phase8.b')::uuid))$$,'account can be reactivated without replacing balance');
select throws_ok($$select public.finance_command(gen_random_uuid(),'transfer',jsonb_build_object('account_id',current_setting('phase8.a'),'destination_id',current_setting('phase8.a'),'amount',100,'description','invalid'))$$,'22023','Different active destination required','self transfer rejected');
select set_config('phase8.category',public.finance_command(gen_random_uuid(),'category_create','{"name":"Rent","type":"despesa"}')->>'id',true);
select set_config('phase8.payable',public.finance_command(gen_random_uuid(),'payable_create',jsonb_build_object('account_id',current_setting('phase8.a'),'category_id',current_setting('phase8.category'),'amount',80,'description','Rent','date','2026-10-01','is_fixed',true,'recurrence','monthly'))#>>'{transaction,id}',true);
select is((select status from public.financial_transactions where id=current_setting('phase8.payable')),'pendente','payable begins pending');
select set_config('phase8.pay_payload',(select jsonb_build_object('id',id,'updated_at',updated_at,'account_id',account_id)::text from public.financial_transactions where id=current_setting('phase8.payable')),true);
select public.finance_command('58000000-0000-0000-0000-000000000012','payable_pay',current_setting('phase8.pay_payload')::jsonb);
select public.finance_command('58000000-0000-0000-0000-000000000012','payable_pay',current_setting('phase8.pay_payload')::jsonb);
select is((select status from public.financial_transactions where id=current_setting('phase8.payable')),'pago','payable is paid');
select is((select count(*)::integer from public.financial_transactions where payable_id=current_setting('phase8.payable')),1,'double submit creates one payment');
select is((select sum(case type when 'receita' then amount else -amount end) from public.financial_transactions where account_id=current_setting('phase8.a')::uuid and entry_role='movement' and status='pago'),820::numeric,'title and movement not counted twice');
select public.finance_command(gen_random_uuid(),'payable_reverse',(select jsonb_build_object('id',id,'updated_at',updated_at) from public.financial_transactions where id=current_setting('phase8.payable')));
select is((select status from public.financial_transactions where id=current_setting('phase8.payable')),'pendente','reversal reopens payable');
select is((select count(*)::integer from public.financial_transactions where reversal_of is not null),1,'compensating movement preserved');
select is((select sum(case type when 'receita' then amount else -amount end) from public.financial_transactions where account_id=current_setting('phase8.a')::uuid and entry_role='movement' and status='pago'),900::numeric,'reversal restores account balance');
select public.finance_command(gen_random_uuid(),'payable_next',(select jsonb_build_object('id',id,'updated_at',updated_at) from public.financial_transactions where id=current_setting('phase8.payable')));
select public.finance_command(gen_random_uuid(),'payable_next',(select jsonb_build_object('id',id,'updated_at',updated_at) from public.financial_transactions where id=current_setting('phase8.payable')));
select is((select count(*)::integer from public.financial_transactions where recurrence_parent_id=current_setting('phase8.payable')),1,'explicit recurrence bounded and unique');
select public.finance_command(gen_random_uuid(),'payable_cancel',(select jsonb_build_object('id',id,'updated_at',updated_at) from public.financial_transactions where id=current_setting('phase8.payable')));
select ok((select cancelled_at is not null from public.financial_transactions where id=current_setting('phase8.payable')),'pending cancellation preserved');
select ok((select count(*)>0 from public.audit_logs where action='finance.payable_reversed'),'reversal audit appended');
select ok(not has_table_privilege('authenticated','public.financial_transactions','INSERT'),'direct book writes revoked');
select ok(not has_table_privilege('authenticated','public.financial_accounts','UPDATE'),'direct balance metadata writes revoked');
select ok(not has_function_privilege('anon','public.finance_command(uuid,text,jsonb)','EXECUTE'),'anonymous command denied');
select public.finance_command(gen_random_uuid(),'settings_save','{"tax_regime":"simples_nacional","tax_rate":6,"fees":{"pix":1},"loss_rate":2,"variable_rate":3,"contribution_margin":40,"revenue_target":5000,"profit_target":1000}');
select is((select contribution_margin from public.finance_settings),40::numeric,'managerial margin persisted');
select is((select fees->>'pix' from public.finance_settings),'1','method fee persisted');
select ok((public.finance_source()->'settings'->>'tax_rate')::numeric=6,'existing tax setting reused');
select throws_ok($$select public.finance_command(gen_random_uuid(),'settings_save',(select to_jsonb(s)||jsonb_build_object('tax_rate',6,'profit_target','NaN') from public.finance_settings s))$$,'23514',null,'NaN profit target rejected');
select throws_ok($$select public.finance_command(gen_random_uuid(),'settings_save',(select to_jsonb(s)||jsonb_build_object('tax_rate',6,'revenue_target','Infinity') from public.finance_settings s))$$,'23514',null,'infinite revenue target rejected');
select throws_ok($$select public.finance_command(gen_random_uuid(),'settings_save',(select jsonb_build_object('updated_at',updated_at,'tax_regime','outro') from public.finance_settings))$$,'22023','Invalid tax rate','missing tax cannot erase pricing setting');
select throws_ok($$select public.finance_command(gen_random_uuid(),'account_create','{"name":"Rollback account","kind":"bank","amount":99999999999}')$$,'22023','Invalid opening amount','failure after account insert rolls back');
select is((select count(*)::integer from public.financial_accounts where name='Rollback account'),0,'failed opening leaves no partial account');
select throws_ok($$select public.settle_financial_transaction(current_setting('phase8.payable'),'pago',null)$$,'42501','Use finance command for managed entries','legacy RPC cannot bypass managed cancellation');
select public.finance_command(gen_random_uuid(),'payable_create',jsonb_build_object('account_id',current_setting('phase8.a'),'category_id',current_setting('phase8.category'),'amount',10,'description','Future due paid now','date','2030-01-01','pay_now',true));
select is((select (paid_at at time zone 'America/Bahia')::date from public.financial_transactions where description='Pagamento · Future due paid now'),(now() at time zone 'America/Bahia')::date,'pay now cash date differs from future due date');
reset role;
set local role authenticated;
select public.operate_cash_register('open',0,null,null);
select public.operate_cash_register('suprimento',100,'Local test',null);
select set_config('phase8.cash',(select id::text from public.financial_accounts where system_key='cash'),true);
select throws_ok($$select public.finance_command(gen_random_uuid(),'transfer',jsonb_build_object('account_id',current_setting('phase8.cash'),'destination_id',current_setting('phase8.b'),'amount',50,'description','Cash transfer blocked'))$$,'22023','Caixa físico com sessão aberta: use o PDV ou encerre a sessão antes de movimentar pelo Financeiro.','cash transfer blocked while PDV owns session');
select throws_ok($$select public.finance_command(gen_random_uuid(),'payable_create',jsonb_build_object('account_id',current_setting('phase8.cash'),'category_id',current_setting('phase8.category'),'amount',25,'description','Cash expense blocked','pay_now',true))$$,'22023','Caixa físico com sessão aberta: use o PDV ou encerre a sessão antes de movimentar pelo Financeiro.','pay and create rolls back with open physical cash');
select is((select count(*)::integer from public.financial_transactions where description in ('Cash transfer blocked','Cash expense blocked')),0,'blocked cash commands leave no partial entries');
select is((public.operate_cash_register('close',100,null,null)#>>'{session,difference}')::numeric,0::numeric,'closing exact physical cash has no duplicated adjustment');
select lives_ok($$select public.finance_command(gen_random_uuid(),'transfer',jsonb_build_object('account_id',current_setting('phase8.cash'),'destination_id',current_setting('phase8.b'),'amount',50,'description','Cash transfer after closing'))$$,'cash transfer works after PDV closes');
reset role;
create function pg_temp.phase8_fail_second_leg() returns trigger language plpgsql as $$
begin
 if new.source='transfer' and new.type='receita' and new.description='Injected transfer failure' then raise exception 'Injected second leg failure'; end if;
 return new;
end $$;
create trigger phase8_fail_second_leg before insert on public.financial_transactions for each row execute function pg_temp.phase8_fail_second_leg();
set local role authenticated;
select throws_ok($$select public.finance_command('58000000-0000-0000-0000-000000000099','transfer',jsonb_build_object('account_id',current_setting('phase8.a'),'destination_id',current_setting('phase8.b'),'amount',100,'description','Injected transfer failure'))$$,'P0001','Injected second leg failure','failure on second transfer leg rolls back');
select is((select count(*)::integer from public.financial_transactions where transfer_id='58000000-0000-0000-0000-000000000099'),0,'no first leg survives failure');
reset role;
select is((select count(*)::integer from private.finance_commands where operation_id='58000000-0000-0000-0000-000000000099'),0,'failed transfer has no successful receipt');
select is((select count(*)::integer from public.audit_logs where metadata->>'operation_id'='58000000-0000-0000-0000-000000000099'),0,'failed transfer has no successful audit event');
drop trigger phase8_fail_second_leg on public.financial_transactions;
select set_config('request.jwt.claims','{"sub":"58000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::integer from public.financial_accounts),0,'other tenant accounts hidden');
select is((select count(*)::integer from public.finance_settings),0,'other tenant settings hidden');
select throws_ok($$select public.finance_command(gen_random_uuid(),'adjust',jsonb_build_object('account_id',current_setting('phase8.a'),'amount',10,'description','cross tenant','type','receita'))$$,'22023','Active account required','cross tenant command denied');
reset role;
select set_config('request.jwt.claims','{"sub":"58000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into public.role_permissions(company_id,path,roles) select company_id,'/financial',array[]::text[] from public.profiles where auth_user_id='58000000-0000-0000-0000-000000000001' on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select is((select count(*)::integer from public.financial_accounts),0,'financial permission enforced on accounts');
select throws_ok($$select public.finance_source()$$,'42501','Finance access denied','read model permission enforced');
select throws_ok($$select public.finance_command(gen_random_uuid(),'account_create','{"name":"Denied"}')$$,'42501','Finance access denied','command permission enforced');
select is(public.settle_financial_transaction('known-receipt','pago',null)->>'status','NOT_AUTHORIZED','legacy settlement respects explicit denial');
select ok(not has_function_privilege('authenticated','public.settle_financial_transaction_phase4b(text,text,timestamptz)','EXECUTE'),'legacy implementation is not exposed');
select * from finish();
rollback;
